import pyomo.environ as pyo

DATA = {
    "districts": [1, 2, 3, 4],
    "supply":   {1: 412, 2: 92, 3: 265, 4: 342},
    "demand":   {1: 74,  2: 334, 3: 61, 4: 352},
    # cost[i][j] = cost from i to j; self-entries disabled via bounds
    "cost": {
        1: {2: 20, 3: 43, 4: 1},
        2: {1: 42, 3: 32, 4: 13},
        3: {1: 27, 2: 5, 4: 10},
        4: {1: 30, 2: 22, 3: 9},
    },
    "big_m": 1_000_000,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    # --- net surplus / deficit per district ---
    surplus = {i: d["supply"][i] - d["demand"][i] for i in d["districts"]}

    m = pyo.ConcreteModel()
    m.I = pyo.Set(initialize=d["districts"])

    # x[i,j] for i != j; block i==j by making it a fixed-zero variable via bounds
    m.x = pyo.Var(m.I, m.I, within=pyo.NonNegativeIntegers)

    def _cost(i, j):
        return d["cost"][i].get(j, 0)

    # Objective: minimize total transport cost
    def obj_rule(mm):
        return sum(_cost(i, j) * mm.x[i, j]
                   for i in mm.I for j in mm.I if i != j)
    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Diagonals must be zero
    def diag_rule(mm, i):
        return mm.x[i, i] == 0
    m.diag = pyo.Constraint(m.I, rule=diag_rule)

    # Supply: total outflow <= surplus (sources: net-surplus districts)
    def outflow_rule(mm, i):
        return sum(mm.x[i, j] for j in mm.I if j != i) <= surplus[i]
    m.outflow = pyo.Constraint(m.I, rule=outflow_rule)

    # Demand: total inflow >= deficit (destinations need net imports)
    def inflow_rule(mm, j):
        return sum(mm.x[i, j] for i in mm.I if i != j) >= -surplus[j]
    m.inflow = pyo.Constraint(m.I, rule=inflow_rule)

    return m
